mapper.select:
			SELECT 
			    dgtw_req_ctrl_cmd_id,
			    resp_identifier,
			    digital_object_id,
			    federated_twin_id,
			    federated_digital_object_id,
			    digital_twin_id,
			    req_ctrl_command,
			    req_date,
			    req_ctrl_cmd_status
			FROM dgtw_req_ctrl_cmd_info
	  		WHERE 1=1	

  		 	AND dgtw_req_ctrl_cmd_id = #{dgtwReqCtrlCmdId}


  		 	AND req_ctrl_cmd_status = #{reqCtrlCmdStatus}


  		 	AND resp_identifier = #{respIdentifier}


  		 	AND digital_object_id = #{digitalObjectId}


  		 	AND federated_twin_id = #{federatedTwinId}


  		 	AND federated_digital_object_id = #{federatedDigitalObjectId}


  		 	AND digital_twin_id = #{digitalTwinId}


  		 	AND req_ctrl_command = #{reqCtrlCommand}



  		 	AND req_date <=  DATE_ADD(now(3), INTERVAL #{timeSession} MINUTE)

